def shapes_of(g):
    H,W=len(g),len(g[0]); seen=set(); sh=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                sh.append({'col':col,'cells':sorted(cells),'r0':min(ys),'r1':max(ys),'c0':min(xs),'c1':max(xs)})
    return sh

def has_hole(cells,H,W):
    # flood fill background from border on 0-cells within bbox (with 1 padding); any 0 not reached inside bbox = hole
    r0=min(c[0] for c in cells)-1; r1=max(c[0] for c in cells)+1
    c0=min(c[1] for c in cells)-1; c1=max(c[1] for c in cells)+1
    cellset=set(cells)
    # temp grid padded
    h=r1-r0+1; w=c1-c0+1
    grid=[[0]*w for _ in range(h)]
    for y,x in cells: grid[y-r0][x-c0]=1
    seen=set(); stack=[(0,0)]; seen.add((0,0))
    while stack:
        y,x=stack.pop()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0 and (ny,nx) not in seen:
                seen.add((ny,nx)); stack.append((ny,nx))
    return any(grid[y][x]==0 and (y,x) not in seen for y in range(h) for x in range(w))

def transform(g):
    H,W=len(g),len(g[0])
    sh=shapes_of(g)
    for s in sh: s['hole']=has_hole(s['cells'],H,W)
    out=[[0]*W for _ in range(H)]
    # hollow: float up, process by original top row
    for s in sorted([s for s in sh if s['hole']], key=lambda s:s['r0']):
        hgt=s['r1']-s['r0']+1; y=0
        while True:
            occ=any(out[y+dy][x] for dy in range(hgt) for x in range(s['c0'],s['c1']+1))
            if occ: break
            y+=1
            if y+hgt>H: y=H-hgt; break
        for (ry,rx) in s['cells']: out[ry-s['r0']+y][rx]=s['col']
    # open: fall down, process by original bottom row descending
    for s in sorted([s for s in sh if not s['hole']], key=lambda s:-s['r1']):
        hgt=s['r1']-s['r0']+1; y=H-hgt
        while True:
            occ=any(out[y+dy][x] for dy in range(hgt) for x in range(s['c0'],s['c1']+1))
            if occ: break
            y-=1
            if y<0: y=0; break
        y+=1  # last free position
        for (ry,rx) in s['cells']: out[ry-s['r0']+y][rx]=s['col']
    return out

